content:
.outgoing-links header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.outgoing-links header h2 {
  margin: 0;
}

.outgoing-links ul {
  display: grid;
  gap: 0.25rem;
  margin: 0.65rem 0 0;
  padding: 0;
  list-style: none;
}

.outgoing-links button {
  display: flex;
  width: 100%;
  gap: 0.5rem;
  align-items: center;
  justify-content: space-between;
  padding: 0.4rem 0.5rem;
  border: 0;
  border-radius: 0.35rem;
  color: var(--fg);
  background: transparent;
  text-align: left;
}

.outgoing-links button:hover,
.outgoing-links button:focus-visible {
  background: var(--accent-soft);
}

.outgoing-links-empty {
  color: var(--fg-muted);
  font-size: 0.8rem;
}

.wiki-status {
  flex: none;
  padding: 0.1rem 0.3rem;
  border-radius: 999px;
  color: var(--fg-muted);
  background: var(--panel);
  font-size: 0.65rem;
}

.wiki-status.is-resolved {
  color: var(--accent);
  background: var(--accent-soft);
}

.wiki-status.is-ambiguous,
.wiki-status.is-unresolved {
  color: var(--danger);
}
